-- =====================================================================
-- CADASTRO DE TORRES a partir do Registo Mestre ANTOSC (212 sites)
-- Gerado automaticamente a partir do JSON fornecido.
--
-- IMPORTANTE:
--  * Campos que o JSON nao tinha (site_level, load_work_level, latitude,
--    longitude, electrical_id, battery_backup_designed_min, snmp_*, status,
--    availability_30d) ficam de fora do INSERT e assumem os valores DEFAULT
--    da tabela. Preenche-os depois com UPDATE.
--  * region_id e operator_id sao FK para UUID e o JSON so tem o NOME em
--    texto ("Regiao", "Operadoras"). Nao dá para inserir o nome direto num
--    campo UUID, por isso deixei-os de fora e pus o valor original em
--    comentario ao lado de cada INSERT, para tu mapeares para o UUID certo
--    (ou usar sub-select tipo (SELECT region_id FROM regions WHERE nome = 'Norte')).
--  * Sites com Operadoras multiplas (ex: "Unitel,Africell") vao precisar da
--    tabela site_operators depois de teres os operator_id -- deixei o texto
--    em comentario para nao se perder a informacao.
--  * "Rectificador (vendor)" = 'N/A' foi tratado como vendor NAO preenchido
--    (coluna omitida, assume default '').
--  * IPs com valor 'N/A' ou ausentes ficam NULL (coluna omitida).
-- =====================================================================

-- Coluna adicional identificada no JSON que ainda nao estava na migracao anterior:
ALTER TABLE towers ADD COLUMN IF NOT EXISTS has_solar BOOLEAN NOT NULL DEFAULT FALSE; -- "Solar"

-- Garantir que existe gerador de UUID (ajusta para a extensao que tiveres ativa)
CREATE EXTENSION IF NOT EXISTS pgcrypto;

